window.EP = {"name": "ch9", "label": "एपिसोड 9", "en": "The Night the Drums Woke the Gods", "duration": 1274.03, "title": [{"start": 5.5, "end": 6.88, "text": "हिडन उत्तराखंड"}, {"start": 7.43, "end": 10.18, "text": "अ बुक बाय, पार्थ डी. जोशी"}, {"start": 10.73, "end": 15.83, "text": "चैप्टर नाइन। द नाइट द ड्रम्स वोक द गॉड्स"}, {"start": 16.38, "end": 20.17, "text": "डे टेन। सरयू के ऊपर, इजा का गाँव"}], "captions": [{"start": 21.72, "end": 26.27, "text": "हमने पूरी रात, पहाड़ के नीचे, शाओनी का इंतज़ार किया।", "who": "", "voice": "narrator", "diary": false}, {"start": 26.72, "end": 30.41, "text": "हीरा हमें अँधेरे में, चरवाहों के एक रास्ते से,", "who": "", "voice": "narrator", "diary": false}, {"start": 30.41, "end": 31.93, "text": "नीचे वान तक ले आया।", "who": "", "voice": "narrator", "diary": false}, {"start": 31.93, "end": 36.98, "text": "गब्बर बसंती के साथ इंतज़ार कर रहे थे, इंजन चालू, हेडलाइट्स बंद।", "who": "", "voice": "narrator", "diary": false}, {"start": 36.98, "end": 45.87, "text": "हम हीटर चलाकर गाड़ी में बैठे रहे, न सोए, न बोले, और हर बार, जब घाटी की सड़क पर हेडलाइट्स का कोई जोड़ा नीचे आता,", "who": "", "voice": "narrator", "diary": false}, {"start": 45.87, "end": 49.64, "text": "क्षितिज का हाथ अपनी डायरी पर इतनी ज़ोर से कसता,", "who": "", "voice": "narrator", "diary": false}, {"start": 49.64, "end": 52.85, "text": "कि उसकी उँगलियों के जोड़ सफ़ेद पड़ जाते।", "who": "", "voice": "narrator", "diary": false}, {"start": 53.3, "end": 55.3, "text": "सुबह पाँच बजकर बीस मिनट पर,", "who": "", "voice": "narrator", "diary": false}, {"start": 55.3, "end": 58.41, "text": "किसी ने उसके बग़ल वाली खिड़की पर दस्तक दी।", "who": "", "voice": "narrator", "diary": false}, {"start": 58.86, "end": 59.34, "text": "शाओनी।", "who": "", "voice": "narrator", "diary": false}, {"start": 59.34, "end": 66.18, "text": "बालों से लेकर बूटों तक धूल से ढकी, फ़्लीस की एक आस्तीन फटी हुई, गाल पर एक लंबी खरोंच,", "who": "", "voice": "narrator", "diary": false}, {"start": 66.18, "end": 69.08, "text": "और चेहरे पर वो सबसे शांत एक्सप्रेशन,", "who": "", "voice": "narrator", "diary": false}, {"start": 69.08, "end": 72.78, "text": "जो मैंने आज तक किसी इंसान के चेहरे पर देखा है।", "who": "", "voice": "narrator", "diary": false}, {"start": 73.23, "end": 75.14, "text": "क्षितिज ने खिड़की नीचे की।", "who": "", "voice": "narrator", "diary": false}, {"start": 75.14, "end": 78.59, "text": "उसने उसे देखा, फिर उसके पार मुझे, फिर गब्बर को।", "who": "", "voice": "narrator", "diary": false}, {"start": 79.04, "end": 79.59, "text": "चाय है?", "who": "शाओनी", "voice": "shaoni", "diary": false}, {"start": 79.79, "end": 80.48, "text": "उसने पूछा।", "who": "", "voice": "narrator", "diary": false}, {"start": 81.98, "end": 87.67, "text": "उसने हमें कुमाऊँ के रास्ते में बताया, पीछे अपने भाई के साथ बैठे हुए, उसी सपाट,", "who": "", "voice": "narrator", "diary": false}, {"start": 87.67, "end": 90.81, "text": "तथ्यों वाली आवाज़ में, जिसमें वो समझाती है,", "who": "", "voice": "narrator", "diary": false}, {"start": 90.81, "end": 93.65, "text": "कि आपका एक्सेल फ़ॉर्मूला ग़लत क्यों है।", "who": "", "voice": "narrator", "diary": false}, {"start": 94.1, "end": 96.97, "text": "पहली बात जो उसने बताई, उसने सबको हैरान कर दिया।", "who": "", "voice": "narrator", "diary": false}, {"start": 97.42, "end": 98.37, "text": "जब पत्थर गिरे।", "who": "शाओनी", "voice": "shaoni", "diary": false}, {"start": 98.57, "end": 99.27, "text": "उसने कहा,", "who": "", "voice": "narrator", "diary": false}, {"start": 99.47, "end": 100.85, "text": "मैं ग़लत तरफ़ भागी।", "who": "शाओनी", "voice": "shaoni", "diary": false}, {"start": 100.85, "end": 101.72, "text": "ऊपर की तरफ़।", "who": "शाओनी", "voice": "shaoni", "diary": false}, {"start": 101.72, "end": 103.91, "text": "एक पत्थर मेरे पैर के पास गिरा।", "who": "शाओनी", "voice": "shaoni", "diary": false}, {"start": 103.91, "end": 108.42, "text": "और भल्ला ने मुझे जैकेट से पकड़के, एक चट्टान के पीछे खींच लिया।", "who": "शाओनी", "voice": "shaoni", "diary": false}, {"start": 108.42, "end": 109.88, "text": "अपनी पीठ से ढक लिया।", "who": "शाओनी", "voice": "shaoni", "diary": false}, {"start": 109.88, "end": 111.7, "text": "दो पत्थर उसकी पीठ पे लगे।", "who": "शाओनी", "voice": "shaoni", "diary": false}, {"start": 111.9, "end": 112.5, "text": "वो रुकी।", "who": "", "voice": "narrator", "diary": false}, {"start": 112.7, "end": 115.44, "text": "उसने आवाज़ तक नहीं निकाली।", "who": "शाओनी", "voice": "shaoni", "diary": false}, {"start": 115.89, "end": 118.04, "text": "क्षितिज मुड़कर उसे घूरने लगा।", "who": "", "voice": "narrator", "diary": false}, {"start": 118.24, "end": 118.87, "text": "भल्ला ने?", "who": "क्षितिज", "voice": "kshitij", "diary": false}, {"start": 119.32, "end": 119.96, "text": "भल्ला ने।", "who": "शाओनी", "voice": "shaoni", "diary": false}, {"start": 120.16, "end": 123.01, "text": "उसने भौंहें सिकोड़ीं, जैसे कोई इक्वेशन हो,", "who": "", "voice": "narrator", "diary": false}, {"start": 123.01, "end": 125.19, "text": "जो बैलेंस होने से मना कर रही हो।", "who": "", "voice": "narrator", "diary": false}, {"start": 125.39, "end": 126.1, "text": "गुंडा है।", "who": "शाओनी", "voice": "shaoni", "diary": false}, {"start": 126.1, "end": 127.53, "text": "रोहन का कुत्ता है।", "who": "शाओनी", "voice": "shaoni", "diary": false}, {"start": 127.53, "end": 129.83, "text": "मेरे भाई को उठा के ले गया था।", "who": "शाओनी", "voice": "shaoni", "diary": false}, {"start": 129.83, "end": 131.57, "text": "और उसने मेरी जान बचाई।", "who": "शाओनी", "voice": "shaoni", "diary": false}, {"start": 131.57, "end": 132.6, "text": "दोनों सच हैं।", "who": "शाओनी", "voice": "shaoni", "diary": false}, {"start": 132.8, "end": 134.4, "text": "उसने खिड़की से बाहर देखा।", "who": "", "voice": "narrator", "diary": false}, {"start": 134.6, "end": 136.84, "text": "मुझे पसंद नहीं, पर दोनों सच हैं।", "who": "शाओनी", "voice": "shaoni", "diary": false}, {"start": 137.29, "end": 142.34, "text": "पत्थर गिरने के बाद, उसने बताया, भल्ला उसे नीचे भगुवाबासा तक ले गया,", "who": "", "voice": "narrator", "diary": false}, {"start": 142.34, "end": 145.14, "text": "जहाँ रोहन के आदमी एक टेंट छोड़ गए थे।", "who": "", "voice": "narrator", "diary": false}, {"start": 145.14, "end": 145.89, "text": "शराफ़त से।", "who": "", "voice": "narrator", "diary": false}, {"start": 145.89, "end": 146.42, "text": "चुपचाप।", "who": "", "voice": "narrator", "diary": false}, {"start": 146.42, "end": 150.42, "text": "पूरे रास्ते उसके एक क़दम पीछे, किसी बॉडीगार्ड की तरह।", "who": "", "voice": "narrator", "diary": false}, {"start": 150.42, "end": 154.72, "text": "रोहन आगे निकल गया था, भल्ला ने उसे बताया; वो सुबह लौटेगा।", "who": "", "voice": "narrator", "diary": false}, {"start": 154.72, "end": 156.07, "text": "फिर वो बात करेंगे।", "who": "", "voice": "narrator", "diary": false}, {"start": 156.52, "end": 157.09, "text": "रात आई।", "who": "", "voice": "narrator", "diary": false}, {"start": 157.09, "end": 157.89, "text": "हवा थम गई।", "who": "", "voice": "narrator", "diary": false}, {"start": 157.89, "end": 164.49, "text": "शाओनी टेंट के दरवाज़े पर बैठी, भल्ला को देखती रही, जो बाहर एक चट्टान से पीठ टिकाए,", "who": "", "voice": "narrator", "diary": false}, {"start": 164.49, "end": 168.76, "text": "हाथ में टॉर्च लिए, अँधेरे में ठीक वैसे ही घूर रहा था,", "who": "", "voice": "narrator", "diary": false}, {"start": 168.76, "end": 171.98, "text": "जैसे वो देवप्रयाग में घाट को घूर रहा था।", "who": "", "voice": "narrator", "diary": false}, {"start": 171.98, "end": 173.1, "text": "कभी सोता नहीं।", "who": "", "voice": "narrator", "diary": false}, {"start": 173.1, "end": 174.71, "text": "कभी ढीला नहीं पड़ता।", "who": "", "voice": "narrator", "diary": false}, {"start": 174.71, "end": 179.71, "text": "अँधेरे को ऐसे चेक करता हुआ, जैसे अँधेरे पर उसका उधार बाक़ी हो।", "who": "", "voice": "narrator", "diary": false}, {"start": 180.16, "end": 181.57, "text": "आधी रात के आसपास।", "who": "शाओनी", "voice": "shaoni", "diary": false}, {"start": 181.77, "end": 182.47, "text": "उसने कहा,", "who": "", "voice": "narrator", "diary": false}, {"start": 182.67, "end": 184.32, "text": "मैंने उसे बात करते सुना।", "who": "शाओनी", "voice": "shaoni", "diary": false}, {"start": 184.77, "end": 186.77, "text": "मैं अपनी सीट पर पीछे मुड़ा।", "who": "", "voice": "narrator", "diary": false}, {"start": 186.97, "end": 187.47, "text": "किससे?", "who": "", "voice": "narrator", "diary": false}, {"start": 187.47, "end": 188.13, "text": "फ़ोन पे?", "who": "", "voice": "narrator", "diary": false}, {"start": 188.58, "end": 189.45, "text": "फ़ोन नहीं था।", "who": "शाओनी", "voice": "shaoni", "diary": false}, {"start": 189.45, "end": 190.32, "text": "किसी से नहीं।", "who": "शाओनी", "voice": "shaoni", "diary": false}, {"start": 190.52, "end": 191.64, "text": "शाओनी ने मुझे देखा।", "who": "", "voice": "narrator", "diary": false}, {"start": 191.84, "end": 192.73, "text": "अँधेरे से।", "who": "शाओनी", "voice": "shaoni", "diary": false}, {"start": 192.73, "end": 193.62, "text": "बहुत धीरे।", "who": "शाओनी", "voice": "shaoni", "diary": false}, {"start": 193.62, "end": 194.33, "text": "बार-बार।", "who": "शाओनी", "voice": "shaoni", "diary": false}, {"start": 194.33, "end": 198.69, "text": "जैसे बच्चा बुरा सपना भगाने के लिए कुछ दोहराता है।", "who": "शाओनी", "voice": "shaoni", "diary": false}, {"start": 198.89, "end": 202.51, "text": "उसने वो शब्द ठीक वैसे ही कहे, जैसे उसने सुने थे।", "who": "", "voice": "narrator", "diary": false}, {"start": 202.96, "end": 204.08, "text": "माफ़ कर दे, भाई।", "who": "शाओनी", "voice": "shaoni", "diary": false}, {"start": 204.08, "end": 204.85, "text": "माफ़ कर दे।", "who": "शाओनी", "voice": "shaoni", "diary": false}, {"start": 204.85, "end": 206.25, "text": "मैं कुछ नहीं कर सका।", "who": "शाओनी", "voice": "shaoni", "diary": false}, {"start": 206.95, "end": 208.37, "text": "गाड़ी में कोई नहीं बोला।", "who": "", "voice": "narrator", "diary": false}, {"start": 209.07, "end": 209.84, "text": "तब मैंने सोचा।", "who": "शाओनी", "voice": "shaoni", "diary": false}, {"start": 210.04, "end": 211.14, "text": "शाओनी ने आगे कहा।", "who": "", "voice": "narrator", "diary": false}, {"start": 211.34, "end": 211.95, "text": "लॉजिक।", "who": "शाओनी", "voice": "shaoni", "diary": false}, {"start": 211.95, "end": 214.82, "text": "ये आदमी किस चीज़ से डरता है?", "who": "शाओनी", "voice": "shaoni", "diary": false}, {"start": 214.82, "end": 215.84, "text": "हमसे नहीं।", "who": "शाओनी", "voice": "shaoni", "diary": false}, {"start": 215.84, "end": 217.17, "text": "रोहन से नहीं।", "who": "शाओनी", "voice": "shaoni", "diary": false}, {"start": 217.17, "end": 218.2, "text": "अँधेरे से।", "who": "शाओनी", "voice": "shaoni", "diary": false}, {"start": 218.2, "end": 219.83, "text": "पहाड़ की रात से।", "who": "शाओनी", "voice": "shaoni", "diary": false}, {"start": 220.03, "end": 222.58, "text": "उसने अपने हाथों की तरफ़ नीचे देखा।", "who": "", "voice": "narrator", "diary": false}, {"start": 222.78, "end": 226.47, "text": "और अँधेरे में कोई है, जिससे वो माफ़ी माँग रहा है।", "who": "शाओनी", "voice": "shaoni", "diary": false}, {"start": 226.92, "end": 230.53, "text": "तो उसने रात के लगभग एक बजे तक इंतज़ार किया।", "who": "", "voice": "narrator", "diary": false}, {"start": 230.53, "end": 235.66, "text": "फिर वो टेंट के पिछले हिस्से से, बहुत धीरे, रेंगकर बाहर निकली,", "who": "", "voice": "narrator", "diary": false}, {"start": 235.66, "end": 239.61, "text": "नीचे झुके-झुके, पत्थरों के बीच बीस मीटर दूर गई,", "who": "", "voice": "narrator", "diary": false}, {"start": 239.61, "end": 241.21, "text": "और उसका नाम पुकारा।", "who": "", "voice": "narrator", "diary": false}, {"start": 241.66, "end": 242.38, "text": "धीरे से।", "who": "", "voice": "narrator", "diary": false}, {"start": 242.38, "end": 243.46, "text": "लंबा खींचकर।", "who": "", "voice": "narrator", "diary": false}, {"start": 243.46, "end": 246.8, "text": "वैसे ही, जैसे गब्बर ने हमें बताया था,", "who": "", "voice": "narrator", "diary": false}, {"start": 246.8, "end": 250.94, "text": "कि जंगल में ख़बीस किसी मुसाफ़िर को पुकारता है।", "who": "", "voice": "narrator", "diary": false}, {"start": 251.64, "end": 252.76, "text": "भल्…लाआ…", "who": "", "voice": "forest", "diary": false}, {"start": 253.46, "end": 254.5, "text": "भल्ला खड़ा हो गया।", "who": "", "voice": "narrator", "diary": false}, {"start": 255.2, "end": 256.31, "text": "भल्…लाआ…", "who": "", "voice": "forest", "diary": false}, {"start": 257.01, "end": 258.39, "text": "उसने टॉर्च घुमाई।", "who": "", "voice": "narrator", "diary": false}, {"start": 258.39, "end": 260.02, "text": "उसने जवाब नहीं दिया।", "who": "", "voice": "narrator", "diary": false}, {"start": 260.02, "end": 263.43, "text": "उसने आवाज़ की तरफ़ एक भी क़दम नहीं बढ़ाया।", "who": "", "voice": "narrator", "diary": false}, {"start": 263.43, "end": 270.25, "text": "उसने ठीक वही किया, जो इन पहाड़ों के हर बच्चे को सिखाया जाता है: उसने जवाब नहीं दिया,", "who": "", "voice": "narrator", "diary": false}, {"start": 270.25, "end": 271.71, "text": "और पीछा नहीं किया।", "who": "", "voice": "narrator", "diary": false}, {"start": 272.16, "end": 275.89, "text": "उसकी जगह, वो टेंट के अंदर गया, और ज़िप बंद कर ली।", "who": "", "voice": "narrator", "diary": false}, {"start": 276.34, "end": 278.46, "text": "और मैंने चरवाहों वाला रास्ता लिया।", "who": "शाओनी", "voice": "shaoni", "diary": false}, {"start": 278.66, "end": 279.99, "text": "शाओनी ने बात ख़त्म की।", "who": "", "voice": "narrator", "diary": false}, {"start": 280.19, "end": 282.55, "text": "हीरा भैया ने सुबह दिखाया था।", "who": "शाओनी", "voice": "shaoni", "diary": false}, {"start": 282.55, "end": 283.82, "text": "साढ़े चार घंटे।", "who": "शाओनी", "voice": "shaoni", "diary": false}, {"start": 283.82, "end": 284.66, "text": "नीचे आ गई।", "who": "शाओनी", "voice": "shaoni", "diary": false}, {"start": 285.11, "end": 286.92, "text": "गाड़ी में एक लंबी ख़ामोशी रही।", "who": "", "voice": "narrator", "diary": false}, {"start": 287.37, "end": 289.88, "text": "क्षितिज ने उसे तोड़ा, बहुत धीरे से।", "who": "", "voice": "narrator", "diary": false}, {"start": 290.08, "end": 290.47, "text": "दीदी।", "who": "क्षितिज", "voice": "kshitij", "diary": false}, {"start": 290.47, "end": 295.36, "text": "आपने एक ख़बीस की तरह, एक गुंडे को डरा के टेंट में बंद कर दिया।", "who": "क्षितिज", "voice": "kshitij", "diary": false}, {"start": 295.81, "end": 296.56, "text": "लॉजिक।", "who": "शाओनी", "voice": "shaoni", "diary": false}, {"start": 296.76, "end": 297.62, "text": "शाओनी ने कहा।", "who": "", "voice": "narrator", "diary": false}, {"start": 298.07, "end": 298.98, "text": "तीलू रौतेली।", "who": "गब्बर", "voice": "gabbar", "diary": false}, {"start": 299.18, "end": 301.18, "text": "ड्राइवर की सीट से गब्बर ने कहा।", "who": "", "voice": "narrator", "diary": false}, {"start": 301.63, "end": 302.34, "text": "भूत।", "who": "", "voice": "narrator", "diary": false}, {"start": 302.54, "end": 303.33, "text": "मैंने कहा।", "who": "", "voice": "narrator", "diary": false}, {"start": 303.33, "end": 306.32, "text": "एक बार के लिए, किसी ने मुझे टोका नहीं।", "who": "", "voice": "narrator", "diary": false}, {"start": 306.77, "end": 314.7, "text": "उस दिन बहुत बाद में, जब क्षितिज खिड़की से टिककर सो गया था, और गब्बर हेयरपिन मोड़ों पर ध्यान लगाए हुए थे,", "who": "", "voice": "narrator", "diary": false}, {"start": 314.7, "end": 316.84, "text": "शाओनी सीटों के बीच आगे झुकी,", "who": "", "voice": "narrator", "diary": false}, {"start": 316.84, "end": 320.5, "text": "और मुझसे बहुत धीरे से बोली, मेरी तरफ़ देखे बिना।", "who": "", "voice": "narrator", "diary": false}, {"start": 320.95, "end": 321.44, "text": "पार्थ।", "who": "शाओनी", "voice": "shaoni", "diary": false}, {"start": 321.44, "end": 322.01, "text": "कल रात।", "who": "शाओनी", "voice": "shaoni", "diary": false}, {"start": 322.01, "end": 326.35, "text": "जब मैं पत्थरों के बीच छुपी थी, और उसका नाम ले रही थी।", "who": "शाओनी", "voice": "shaoni", "diary": false}, {"start": 326.55, "end": 327.15, "text": "वो रुकी।", "who": "", "voice": "narrator", "diary": false}, {"start": 327.35, "end": 329.08, "text": "मैं बहुत डर गई थी।", "who": "शाओनी", "voice": "shaoni", "diary": false}, {"start": 329.53, "end": 333.4, "text": "जितने साल से मैं उसे जानता हूँ, उसने ये वाक्य कभी नहीं कहा।", "who": "", "voice": "narrator", "diary": false}, {"start": 333.4, "end": 335.17, "text": "मैंने कोई मज़ाक़ नहीं किया।", "who": "", "voice": "narrator", "diary": false}, {"start": 335.17, "end": 336.21, "text": "मैं सीख रहा हूँ।", "who": "", "voice": "narrator", "diary": false}, {"start": 336.66, "end": 337.2, "text": "पता है।", "who": "", "voice": "narrator", "diary": false}, {"start": 337.4, "end": 338.2, "text": "मैंने उससे कहा।", "who": "", "voice": "narrator", "diary": false}, {"start": 338.4, "end": 339.98, "text": "इसीलिए तो तुम तीलू हो।", "who": "", "voice": "narrator", "diary": false}, {"start": 339.98, "end": 342.13, "text": "बिना डर के कोई तीलू नहीं होता।", "who": "", "voice": "narrator", "diary": false}, {"start": 342.13, "end": 343.28, "text": "बस लंबी होती है।", "who": "", "voice": "narrator", "diary": false}, {"start": 343.73, "end": 346.82, "text": "उसने नाक से हँसी निकाली, और पीछे टिक गई।", "who": "", "voice": "narrator", "diary": false}, {"start": 346.82, "end": 352.85, "text": "और पास के उस पार की बाक़ी ड्राइव में, उसने अपना हेडलैंप अपनी गोद में जलाए रखा,", "who": "", "voice": "narrator", "diary": false}, {"start": 352.85, "end": 354.55, "text": "दिन के पूरे उजाले में,", "who": "", "voice": "narrator", "diary": false}, {"start": 354.55, "end": 357.87, "text": "और हम में से किसी ने इसका ज़िक्र नहीं किया।", "who": "", "voice": "narrator", "diary": false}, {"start": 359.37, "end": 361.42, "text": "हमें कहीं ग़ायब होना था।", "who": "", "voice": "narrator", "diary": false}, {"start": 361.42, "end": 364.31, "text": "गब्बर पहले ही तय कर चुके थे, कहाँ।", "who": "", "voice": "narrator", "diary": false}, {"start": 364.76, "end": 366.36, "text": "मेरी इजा का गाँव।", "who": "गब्बर", "voice": "gabbar", "diary": false}, {"start": 366.56, "end": 368.72, "text": "उन्होंने सड़क पर नज़रें टिकाए मुझसे कहा।", "who": "", "voice": "narrator", "diary": false}, {"start": 368.92, "end": 370.06, "text": "बागेश्वर के ऊपर।", "who": "गब्बर", "voice": "gabbar", "diary": false}, {"start": 370.06, "end": 372.28, "text": "वहाँ कोई बसंती को नहीं ढूँढेगा।", "who": "गब्बर", "voice": "gabbar", "diary": false}, {"start": 372.48, "end": 374.13, "text": "उन्होंने मेरी तरफ़ एक नज़र डाली।", "who": "", "voice": "narrator", "diary": false}, {"start": 374.33, "end": 376.35, "text": "और आज रात वहाँ जागर है।", "who": "गब्बर", "voice": "gabbar", "diary": false}, {"start": 376.35, "end": 377.13, "text": "वो लड़का।", "who": "गब्बर", "voice": "gabbar", "diary": false}, {"start": 377.13, "end": 377.75, "text": "याद है?", "who": "गब्बर", "voice": "gabbar", "diary": false}, {"start": 378.2, "end": 379.28, "text": "मुझे याद था।", "who": "", "voice": "narrator", "diary": false}, {"start": 379.28, "end": 380.18, "text": "चैप्टर टू।", "who": "", "voice": "narrator", "diary": false}, {"start": 380.18, "end": 381.18, "text": "ढाबे की आग।", "who": "", "voice": "narrator", "diary": false}, {"start": 381.18, "end": 383.62, "text": "गाँव में जागर होने वाला है।", "who": "", "voice": "narrator", "diary": false}, {"start": 383.62, "end": 385.07, "text": "एक लड़के के लिए।", "who": "", "voice": "narrator", "diary": false}, {"start": 385.07, "end": 388.68, "text": "बुज़ुर्ग कहते हैं, उसे मसान ने पकड़ा है।", "who": "", "voice": "narrator", "diary": false}, {"start": 388.68, "end": 392.12, "text": "और गब्बर का कहना: मैंने कहा, सीज़न है।", "who": "", "voice": "narrator", "diary": false}, {"start": 392.82, "end": 394.56, "text": "वो अब सीज़न नहीं कह रहे थे।", "who": "", "voice": "narrator", "diary": false}, {"start": 395.26, "end": 403.94, "text": "हम ग्वालदम के पास से, गढ़वाल से बाहर निकले, और नीचे कुमाऊँ में उतरे, और पहाड़ बदल गए: ज़्यादा नरम,", "who": "", "voice": "narrator", "diary": false}, {"start": 403.94, "end": 409.62, "text": "ज़्यादा हरे, चीड़ की जगह देवदार, घर चटक नीले और गुलाबी रंगे हुए,", "who": "", "voice": "narrator", "diary": false}, {"start": 409.62, "end": 412.98, "text": "नक़्क़ाशीदार लकड़ी के दरवाज़ों के साथ।", "who": "", "voice": "narrator", "diary": false}, {"start": 412.98, "end": 417.95, "text": "गब्बर की माँ का गाँव, सरयू घाटी के ऊपर एक धार पर बसा था,", "who": "", "voice": "narrator", "diary": false}, {"start": 417.95, "end": 422.2, "text": "एक मंदिर और पत्थर के एक बड़े आँगन के चारों तरफ़,", "who": "", "voice": "narrator", "diary": false}, {"start": 422.2, "end": 425.3, "text": "स्लेट की छतों वाले घरों का एक झुंड।", "who": "", "voice": "narrator", "diary": false}, {"start": 425.75, "end": 432.62, "text": "गब्बर की माँ, जिन्हें हर कोई, गब्बर समेत, इजा कहता था, हरे कार्डिगन में एक छोटी सी औरत थीं,", "who": "", "voice": "narrator", "diary": false}, {"start": 432.62, "end": 436.92, "text": "और बसंती के रुकने से पहले ही वो अपने दरवाज़े पर खड़ी थीं,", "who": "", "voice": "narrator", "diary": false}, {"start": 436.92, "end": 440.69, "text": "जैसे उन्होंने तीन घाटियाँ दूर से इंजन सुन लिया हो।", "who": "", "voice": "narrator", "diary": false}, {"start": 441.14, "end": 442.77, "text": "गब्बर गाड़ी से उतरे।", "who": "", "voice": "narrator", "diary": false}, {"start": 442.77, "end": 444.49, "text": "बड़े आदमी हैं, गब्बर।", "who": "", "voice": "narrator", "diary": false}, {"start": 444.49, "end": 446.86, "text": "पचास साल के, झाड़ू जैसी मूँछ,", "who": "", "voice": "narrator", "diary": false}, {"start": 446.86, "end": 449.72, "text": "हाथों में तीस साल की पहाड़ी सड़कें।", "who": "", "voice": "narrator", "diary": false}, {"start": 449.72, "end": 452.82, "text": "वो रास्ते से अपनी माँ की तरफ़ ऐसे चले,", "who": "", "voice": "narrator", "diary": false}, {"start": 452.82, "end": 456.09, "text": "जैसे कोई लड़का, जिसने खिड़की तोड़ दी हो।", "who": "", "voice": "narrator", "diary": false}, {"start": 456.54, "end": 457.38, "text": "दो साल।", "who": "इजा", "voice": "ija", "diary": false}, {"start": 457.58, "end": 458.6, "text": "इजा ने उनसे कहा।", "who": "", "voice": "narrator", "diary": false}, {"start": 459.05, "end": 459.44, "text": "इजा…", "who": "गब्बर", "voice": "gabbar", "diary": false}, {"start": 459.89, "end": 467.56, "text": "उन्होंने ऊपर हाथ बढ़ाया, और उन्हें काफ़ी ऊपर तक बढ़ाना पड़ा, और उनके सिर की एक तरफ़ एक बार चपत लगाई,", "who": "", "voice": "narrator", "diary": false}, {"start": 467.56, "end": 472.09, "text": "ज़ोर से नहीं, वैसे, जैसे आप किसी दरवाज़े पर दस्तक देते हैं।", "who": "", "voice": "narrator", "diary": false}, {"start": 472.09, "end": 477.0, "text": "फिर उन्होंने दोनों हाथों से उनका चेहरा अपने चेहरे तक नीचे खींचा,", "who": "", "voice": "narrator", "diary": false}, {"start": 477.0, "end": 480.84, "text": "और उसे एक लंबे पल तक वहीं थामे रखा, आँखें बंद किए।", "who": "", "voice": "narrator", "diary": false}, {"start": 481.29, "end": 483.63, "text": "फिर उन्होंने छोड़ा, उनके पार,", "who": "", "voice": "narrator", "diary": false}, {"start": 483.63, "end": 487.84, "text": "गाड़ी के पास अटपटे से खड़े हम तीनों को देखा, और कहा,", "who": "", "voice": "narrator", "diary": false}, {"start": 488.04, "end": 490.22, "text": "सब कमज़ोर दिख रहे हो।", "who": "इजा", "voice": "ija", "diary": false}, {"start": 490.42, "end": 495.21, "text": "और उन्होंने हमें तब तक खिलाया, जब तक हम हिल भी न सकें।", "who": "", "voice": "narrator", "diary": false}, {"start": 495.66, "end": 499.17, "text": "उन्होंने बिना पूछे शाओनी की खरोंच पर हल्दी लगा दी।", "who": "", "voice": "narrator", "diary": false}, {"start": 499.17, "end": 503.04, "text": "उन्होंने बिना पूछे क्षितिज के सिर पर एक ऊनी टोपी रख दी।", "who": "", "voice": "narrator", "diary": false}, {"start": 503.04, "end": 506.27, "text": "उन्होंने कुछ देर मुझे देखा, और फिर, बिना पूछे,", "who": "", "voice": "narrator", "diary": false}, {"start": 506.27, "end": 509.51, "text": "मुझे भट्ट की चुड़कानी का दूसरा हिस्सा दे दिया,", "who": "", "voice": "narrator", "diary": false}, {"start": 509.51, "end": 511.97, "text": "जो गले लगाने का कुमाऊँनी वर्ज़न है।", "who": "", "voice": "narrator", "diary": false}, {"start": 512.42, "end": 514.75, "text": "आधे लंच पर, गब्बर का फ़ोन बजा,", "who": "", "voice": "narrator", "diary": false}, {"start": 514.75, "end": 518.39, "text": "और वो उसे लेकर मुस्कुराते हुए आँगन में निकल गए।", "who": "", "voice": "narrator", "diary": false}, {"start": 518.39, "end": 520.57, "text": "खिड़की से मैंने उन्हें सुना:", "who": "", "voice": "narrator", "diary": false}, {"start": 520.77, "end": 521.77, "text": "हाँ, पहुँच गए।", "who": "गब्बर", "voice": "gabbar", "diary": false}, {"start": 521.77, "end": 522.56, "text": "इजा के पास।", "who": "गब्बर", "voice": "gabbar", "diary": false}, {"start": 522.56, "end": 525.37, "text": "हाँ, खाना खा रहे हैं, भट्ट की चुड़कानी।", "who": "गब्बर", "voice": "gabbar", "diary": false}, {"start": 525.37, "end": 528.53, "text": "हाँ, तेरे लिए भी बचाऊँगी बोलती है, आ जा कभी…", "who": "गब्बर", "voice": "gabbar", "diary": false}, {"start": 528.73, "end": 533.85, "text": "और वो हँसे, उस आदमी की आसान हँसी, जो परिवार से बात कर रहा हो।", "who": "", "voice": "narrator", "diary": false}, {"start": 534.3, "end": 536.26, "text": "मैंने उसके बारे में नहीं सोचा।", "who": "", "voice": "narrator", "diary": false}, {"start": 536.26, "end": 537.04, "text": "क्यों सोचता?", "who": "", "voice": "narrator", "diary": false}, {"start": 537.04, "end": 539.07, "text": "मैं भट्ट की चुड़कानी खा रहा था।", "who": "", "voice": "narrator", "diary": false}, {"start": 539.52, "end": 542.39, "text": "गब्बर अंदर आए, और अपनी माँ के बग़ल में बैठ गए।", "who": "", "voice": "narrator", "diary": false}, {"start": 542.39, "end": 544.32, "text": "उन्होंने उनके घुटने पर हाथ रखा,", "who": "", "voice": "narrator", "diary": false}, {"start": 544.32, "end": 547.69, "text": "और बाक़ी खाने तक वहीं रखे रहीं, और उन्होंने रखने दिया।", "who": "", "voice": "narrator", "diary": false}, {"start": 547.69, "end": 551.55, "text": "मुझे नहीं लगता, उन्होंने तीस साल में किसी को ऐसा करने दिया था।", "who": "", "voice": "narrator", "diary": false}, {"start": 552.0, "end": 555.27, "text": "मैं दोपहर में उनकी रसोई में सो गया, और जागा,", "who": "", "voice": "narrator", "diary": false}, {"start": 555.27, "end": 559.73, "text": "तो मेरे ऊपर एक कंबल था, और आँगन में ढोल ट्यून होने की आवाज़।", "who": "", "voice": "narrator", "diary": false}, {"start": 561.23, "end": 561.71, "text": "रीडर।", "who": "", "voice": "narrator", "diary": false}, {"start": 562.41, "end": 565.93, "text": "यहाँ से इस चैप्टर के आख़िर तक, कोई मज़ाक़ नहीं।", "who": "", "voice": "narrator", "diary": false}, {"start": 566.38, "end": 568.81, "text": "मैंने आपको ऑथर्स नोट में बताया था,", "who": "", "voice": "narrator", "diary": false}, {"start": 568.81, "end": 572.24, "text": "कि जब ढोल शुरू होते हैं, मज़ाक़ बंद हो जाते हैं।", "who": "", "voice": "narrator", "diary": false}, {"start": 572.24, "end": 574.75, "text": "तब मैंने उसे एक नियम की तरह कहा था।", "who": "", "voice": "narrator", "diary": false}, {"start": 574.75, "end": 576.18, "text": "आज रात वो कुछ और है।", "who": "", "voice": "narrator", "diary": false}, {"start": 576.18, "end": 577.54, "text": "मैं मानने वाला हूँ।", "who": "", "voice": "narrator", "diary": false}, {"start": 577.54, "end": 581.19, "text": "मैं आपको वो बताना चाहता हूँ, जो मैंने देखा, उस तरह,", "who": "", "voice": "narrator", "diary": false}, {"start": 581.19, "end": 585.91, "text": "जैसे आप किसी को अपने घर की पूजा के बारे में बताते हैं: सावधानी से,", "who": "", "voice": "narrator", "diary": false}, {"start": 585.91, "end": 586.92, "text": "और हाथ जोड़कर।", "who": "", "voice": "narrator", "diary": false}, {"start": 587.37, "end": 590.65, "text": "जागर, जागा से आता है, यानी जगाना।", "who": "", "voice": "narrator", "diary": false}, {"start": 591.1, "end": 595.95, "text": "ये गढ़वाल और कुमाऊँ के पहाड़ों की एक रात-भर की रस्म है,", "who": "", "voice": "narrator", "diary": false}, {"start": 595.95, "end": 601.6, "text": "और इसका मक़सद ठीक वही है, जो इसका नाम कहता है: देवताओं को जगाना।", "who": "", "voice": "narrator", "diary": false}, {"start": 601.6, "end": 605.75, "text": "माना जाता है, कि स्थानीय देवता, किसी परिवार के,", "who": "", "voice": "narrator", "diary": false}, {"start": 605.75, "end": 609.54, "text": "किसी गाँव के, किसी घाटी के देवता, सोते हैं।", "who": "", "voice": "narrator", "diary": false}, {"start": 609.54, "end": 612.72, "text": "जागर में उन्हें वापस बुलाया जाता है,", "who": "", "voice": "narrator", "diary": false}, {"start": 612.72, "end": 617.75, "text": "एक रात के लिए दुनिया में नीचे आने का न्योता दिया जाता है,", "who": "", "voice": "narrator", "diary": false}, {"start": 617.75, "end": 619.61, "text": "और मदद माँगी जाती है।", "who": "", "voice": "narrator", "diary": false}, {"start": 619.61, "end": 620.05, "text": "इलाज।", "who": "", "voice": "narrator", "diary": false}, {"start": 620.05, "end": 620.67, "text": "इंसाफ़।", "who": "", "voice": "narrator", "diary": false}, {"start": 620.67, "end": 625.43, "text": "किसी ऐसे सवाल का जवाब, जिसका जवाब कोई और नहीं दे सकता।", "who": "", "voice": "narrator", "diary": false}, {"start": 625.88, "end": 630.45, "text": "ये रात को होता है, उस परिवार के घर में, जिसे मदद चाहिए,", "who": "", "voice": "narrator", "diary": false}, {"start": 630.45, "end": 634.76, "text": "और इसके लिए सबसे ज़्यादा दो लोगों की ज़रूरत होती है।", "who": "", "voice": "narrator", "diary": false}, {"start": 635.21, "end": 637.44, "text": "जगरिया, गाने वाला होता है।", "who": "", "voice": "narrator", "diary": false}, {"start": 637.44, "end": 643.43, "text": "आज रात वो सफ़ेद दाढ़ी के खूँटों और ऊन की वास्कट वाला एक बूढ़ा आदमी था,", "who": "", "voice": "narrator", "diary": false}, {"start": 643.43, "end": 648.65, "text": "आँगन में एक कंबल पर पालथी मारे बैठा, बग़ल में एक हुड़का दबाए,", "who": "", "voice": "narrator", "diary": false}, {"start": 648.65, "end": 651.65, "text": "रेत-घड़ी की शक्ल का एक छोटा सा ढोल।", "who": "", "voice": "narrator", "diary": false}, {"start": 651.65, "end": 654.21, "text": "उसके पास दो जवान आदमी बैठे थे,", "who": "", "voice": "narrator", "diary": false}, {"start": 654.21, "end": 659.35, "text": "पीतल की एक बड़ी थाली और एक डंडी लिए, और बाद में ढोल और दमाऊ।", "who": "", "voice": "narrator", "diary": false}, {"start": 659.35, "end": 665.26, "text": "जगरिया देवता की कहानी बिल्कुल शुरुआत से गाता है, लंबे-लंबे छंदों में,", "who": "", "voice": "narrator", "diary": false}, {"start": 665.26, "end": 669.37, "text": "देवता की पूरी ज़िंदगी, और ढोल उसे उठाए चलते हैं।", "who": "", "voice": "narrator", "diary": false}, {"start": 669.82, "end": 672.73, "text": "डंगरिया वो होता है, जिसमें देवता आता है।", "who": "", "voice": "narrator", "diary": false}, {"start": 672.73, "end": 677.03, "text": "आज रात वो एक शांत, अधेड़ उम्र का आदमी था, सफ़ेद कुर्ते में,", "who": "", "voice": "narrator", "diary": false}, {"start": 677.03, "end": 681.11, "text": "पास के गाँव का एक किसान, आग के दूसरी तरफ़ आँखें बंद किए,", "who": "", "voice": "narrator", "diary": false}, {"start": 681.11, "end": 682.79, "text": "बिल्कुल स्थिर बैठा हुआ।", "who": "", "voice": "narrator", "diary": false}, {"start": 682.79, "end": 687.45, "text": "कुमाऊँनी में, गब्बर ने मेरे कान में कहा, डंगर का मतलब है रास्ता।", "who": "", "voice": "narrator", "diary": false}, {"start": 687.45, "end": 691.24, "text": "डंगरिया वो रास्ता है, जिस पर चलकर देवता नीचे आता है।", "who": "", "voice": "narrator", "diary": false}, {"start": 691.69, "end": 694.77, "text": "परिवार पास बैठा था: माँ, पिता, दादी।", "who": "", "voice": "narrator", "diary": false}, {"start": 694.77, "end": 697.68, "text": "और लड़का, दुबला, लगभग चौदह साल का,", "who": "", "voice": "narrator", "diary": false}, {"start": 697.68, "end": 701.61, "text": "एक शॉल में लिपटा हुआ, आँखों के नीचे काले घेरे।", "who": "", "voice": "narrator", "diary": false}, {"start": 701.61, "end": 706.66, "text": "इजा ने मुझे बहुत धीरे से बताया, कि वो दो महीने से बीमार था।", "who": "", "voice": "narrator", "diary": false}, {"start": 706.66, "end": 707.26, "text": "बुख़ार।", "who": "", "voice": "narrator", "diary": false}, {"start": 707.26, "end": 708.11, "text": "बुरे सपने।", "who": "", "voice": "narrator", "diary": false}, {"start": 708.11, "end": 709.74, "text": "नींद में बड़बड़ाना।", "who": "", "voice": "narrator", "diary": false}, {"start": 709.74, "end": 714.35, "text": "बागेश्वर और हल्द्वानी के डॉक्टरों को कुछ नहीं मिला था।", "who": "", "voice": "narrator", "diary": false}, {"start": 714.35, "end": 717.26, "text": "वो नदी किनारे के श्मशान के पास से,", "who": "", "voice": "narrator", "diary": false}, {"start": 717.26, "end": 721.02, "text": "देर रात अकेले घर लौटने के बाद बीमार पड़ा था।", "who": "", "voice": "narrator", "diary": false}, {"start": 721.47, "end": 724.67, "text": "बुज़ुर्ग कहते थे, उसे मसान ने पकड़ा है।", "who": "", "voice": "narrator", "diary": false}, {"start": 725.12, "end": 729.84, "text": "इजा ने जो बताया, मैं उसकी तीन मेडिकल वजहें आपको गिना सकता हूँ।", "who": "", "voice": "narrator", "diary": false}, {"start": 729.84, "end": 732.05, "text": "मैं उनके आँगन में बैठा भी था।", "who": "", "voice": "narrator", "diary": false}, {"start": 732.05, "end": 734.95, "text": "तो मैं आपको सिर्फ़ वो बताऊँगा, जो हुआ।", "who": "", "voice": "narrator", "diary": false}, {"start": 735.4, "end": 737.55, "text": "जगरिया ने अँधेरा होते ही शुरू किया।", "who": "", "voice": "narrator", "diary": false}, {"start": 738.0, "end": 744.77, "text": "उसने धीरे से शुरू किया, हुड़का उसकी उँगलियों के नीचे किसी धड़कन की तरह टिक-टिक करता हुआ,", "who": "", "voice": "narrator", "diary": false}, {"start": 744.77, "end": 749.16, "text": "उसकी आवाज़ पुरानी कुमाऊँनी की लंबी लाइनों में उठती-गिरती,", "who": "", "voice": "narrator", "diary": false}, {"start": 749.16, "end": 751.93, "text": "जिसे मैं शब्द-दर-शब्द समझ नहीं पाया,", "who": "", "voice": "narrator", "diary": false}, {"start": 751.93, "end": 754.24, "text": "पर समझने की ज़रूरत भी नहीं थी।", "who": "", "voice": "narrator", "diary": false}, {"start": 754.24, "end": 758.47, "text": "गब्बर पास झुके, और मेरे कान में उसकी रूपरेखा बताते रहे।", "who": "", "voice": "narrator", "diary": false}, {"start": 758.92, "end": 765.51, "text": "वो गोलू देवता के बारे में गा रहा था, कुमाऊँ के इंसाफ़ के देवता: चंपावत के एक राजा,", "who": "", "voice": "narrator", "diary": false}, {"start": 765.51, "end": 769.44, "text": "झल राय, और उनकी सबसे छोटी रानी, कालिंका, के बेटे।", "who": "", "voice": "narrator", "diary": false}, {"start": 769.44, "end": 775.54, "text": "वो जलनखोर बड़ी रानियाँ, जिन्होंने नवजात को चुराकर उसकी जगह एक पत्थर रख दिया,", "who": "", "voice": "narrator", "diary": false}, {"start": 775.54, "end": 777.95, "text": "और बच्चे को नदी में फेंक दिया।", "who": "", "voice": "narrator", "diary": false}, {"start": 777.95, "end": 779.88, "text": "वो मछुआरा, जिसे वो मिला।", "who": "", "voice": "narrator", "diary": false}, {"start": 779.88, "end": 785.9, "text": "वो लड़का, जो बड़ा होकर एक लकड़ी के घोड़े पर महल तक गया, और रानियों से पूछा,", "who": "", "voice": "narrator", "diary": false}, {"start": 785.9, "end": 790.32, "text": "कि क्या लकड़ी का घोड़ा पानी पी सकता है, और जब वो हँसीं,", "who": "", "voice": "narrator", "diary": false}, {"start": 790.32, "end": 794.81, "text": "तो उनसे पूछा, कि क्या कोई रानी पत्थर को जन्म दे सकती है।", "who": "", "voice": "narrator", "diary": false}, {"start": 794.81, "end": 797.3, "text": "वो राजा, जिसे आख़िरकार समझ आया।", "who": "", "voice": "narrator", "diary": false}, {"start": 797.3, "end": 801.56, "text": "वो लड़का, जो वो देवता बना, जिसके पास लोग तब जाते हैं,", "who": "", "voice": "narrator", "diary": false}, {"start": 801.56, "end": 804.13, "text": "जब जाने के लिए कोई और नहीं होता।", "who": "", "voice": "narrator", "diary": false}, {"start": 804.58, "end": 808.95, "text": "फिर जगरिया ने गंगनाथ के बारे में गाया: डोटी का एक राजकुमार,", "who": "", "voice": "narrator", "diary": false}, {"start": 808.95, "end": 813.17, "text": "जिसने भाना नाम की एक औरत के प्यार में अपना राज छोड़ दिया,", "who": "", "voice": "narrator", "diary": false}, {"start": 813.17, "end": 815.76, "text": "और इसके लिए उसका क़त्ल कर दिया गया।", "who": "", "voice": "narrator", "diary": false}, {"start": 815.76, "end": 820.73, "text": "और कैसे, उसकी मौत के बाद, उसकी बेचैन आत्मा ने लोगों को परेशान किया,", "who": "", "voice": "narrator", "diary": false}, {"start": 820.73, "end": 823.69, "text": "जब तक उन्होंने उसे पूजना शुरू नहीं किया,", "who": "", "voice": "narrator", "diary": false}, {"start": 823.69, "end": 826.73, "text": "उसे और भाना को साथ, और परेशानी बंद हो गई।", "who": "", "voice": "narrator", "diary": false}, {"start": 826.73, "end": 828.51, "text": "एक भूत, जो देवता बन गया।", "who": "", "voice": "narrator", "diary": false}, {"start": 828.51, "end": 830.8, "text": "क्षितिज ने वो लाइन दो बार लिखी।", "who": "", "voice": "narrator", "diary": false}, {"start": 831.25, "end": 834.87, "text": "गब्बर पूरी रात इजा के बग़ल में कंबल पर बैठे रहे,", "who": "", "voice": "narrator", "diary": false}, {"start": 834.87, "end": 837.43, "text": "पालथी मारे, अपनी टोपी गोद में रखे।", "who": "", "voice": "narrator", "diary": false}, {"start": 837.43, "end": 839.85, "text": "मैंने आग से ज़्यादा उन्हें देखा।", "who": "", "voice": "narrator", "diary": false}, {"start": 839.85, "end": 844.29, "text": "उन्हें धुनें आती थीं, ये उनके सिर हिलने के ढंग से दिखता था,", "who": "", "voice": "narrator", "diary": false}, {"start": 844.29, "end": 847.38, "text": "पर शब्द नहीं; वो एक लाइन होंठों से बोलते,", "who": "", "voice": "narrator", "diary": false}, {"start": 847.38, "end": 850.85, "text": "उसे खो देते, और दो लाइन बाद उसे फिर पकड़ लेते।", "who": "", "voice": "narrator", "diary": false}, {"start": 850.85, "end": 858.69, "text": "एक बार, जब जगरिया एक ऐसे छंद पर पहुँचा, जो एक बेटे के बारे में था, जो घर छोड़कर मैदानों में चला जाता है,", "who": "", "voice": "narrator", "diary": false}, {"start": 858.69, "end": 862.01, "text": "और अपने गाँव के गीत भूल जाता है, मैंने देखा,", "who": "", "voice": "narrator", "diary": false}, {"start": 862.01, "end": 865.02, "text": "इजा का हाथ कंबल पर उनका हाथ ढूँढ रहा था।", "who": "", "voice": "narrator", "diary": false}, {"start": 865.02, "end": 868.04, "text": "दोनों में से किसी ने दूसरे को नहीं देखा।", "who": "", "voice": "narrator", "diary": false}, {"start": 868.49, "end": 869.8, "text": "घंटे पर घंटा।", "who": "", "voice": "narrator", "diary": false}, {"start": 869.8, "end": 871.51, "text": "ढोल तेज़ होते गए।", "who": "", "voice": "narrator", "diary": false}, {"start": 871.51, "end": 873.93, "text": "ढोल और दमाऊ शामिल हो गए।", "who": "", "voice": "narrator", "diary": false}, {"start": 873.93, "end": 874.83, "text": "थाली बजी।", "who": "", "voice": "narrator", "diary": false}, {"start": 874.83, "end": 878.96, "text": "आग ने चिंगारियाँ एक ऐसे आसमान में उछालीं,", "who": "", "voice": "narrator", "diary": false}, {"start": 878.96, "end": 884.51, "text": "जो तारों से इतना भरा था, कि बिखरे हुए नमक जैसा लगता था।", "who": "", "voice": "narrator", "diary": false}, {"start": 884.96, "end": 889.71, "text": "और आँगन के बिल्कुल पीछे, मंदिर की दीवार की छाँव में,", "who": "", "voice": "narrator", "diary": false}, {"start": 889.71, "end": 894.47, "text": "मैंने किसी को देखा, जिसे आते हुए मैंने नहीं देखा था।", "who": "", "voice": "narrator", "diary": false}, {"start": 895.17, "end": 895.89, "text": "गोलू।", "who": "", "voice": "narrator", "diary": false}, {"start": 896.59, "end": 898.18, "text": "कोई रिंग लाइट नहीं।", "who": "", "voice": "narrator", "diary": false}, {"start": 898.18, "end": 899.43, "text": "कोई कैमरा नहीं।", "who": "", "voice": "narrator", "diary": false}, {"start": 899.43, "end": 901.19, "text": "हाथ में फ़ोन तक नहीं।", "who": "", "voice": "narrator", "diary": false}, {"start": 901.19, "end": 905.29, "text": "बस पफ़र जैकेट और एक पुरानी नीली टोपी में एक आदमी,", "who": "", "voice": "narrator", "diary": false}, {"start": 905.29, "end": 907.79, "text": "बिल्कुल स्थिर खड़ा, सुनता हुआ।", "who": "", "voice": "narrator", "diary": false}, {"start": 907.79, "end": 910.22, "text": "उसने मुझे उसे देखते हुए देखा।", "who": "", "voice": "narrator", "diary": false}, {"start": 910.22, "end": 911.89, "text": "उसने नज़र नहीं हटाई।", "who": "", "voice": "narrator", "diary": false}, {"start": 911.89, "end": 912.98, "text": "वो हिला नहीं।", "who": "", "voice": "narrator", "diary": false}, {"start": 913.43, "end": 914.65, "text": "मैंने कुछ नहीं कहा।", "who": "", "voice": "narrator", "diary": false}, {"start": 914.65, "end": 915.29, "text": "यहाँ नहीं।", "who": "", "voice": "narrator", "diary": false}, {"start": 915.29, "end": 916.07, "text": "आज रात नहीं।", "who": "", "voice": "narrator", "diary": false}, {"start": 916.52, "end": 920.7, "text": "सुबह के तीन बजे के थोड़ी देर बाद, डंगरिया काँपने लगा।", "who": "", "voice": "narrator", "diary": false}, {"start": 921.15, "end": 923.86, "text": "ये उसके हाथों से शुरू हुआ।", "who": "", "voice": "narrator", "diary": false}, {"start": 923.86, "end": 925.33, "text": "फिर उसके कंधे।", "who": "", "voice": "narrator", "diary": false}, {"start": 925.33, "end": 927.0, "text": "ढोल और तेज़ हुए।", "who": "", "voice": "narrator", "diary": false}, {"start": 927.0, "end": 933.38, "text": "जगरिया की आवाज़ चढ़ती गई, चढ़ती गई, पुकारती हुई, पुकारती हुई।", "who": "", "voice": "narrator", "diary": false}, {"start": 933.38, "end": 939.65, "text": "डंगरिया का पूरा शरीर थरथराने लगा, उसका सिर पीछे लुढ़कता हुआ,", "who": "", "voice": "narrator", "diary": false}, {"start": 939.65, "end": 943.83, "text": "उसकी साँस छोटी, कड़ी हाँफों में आती हुई।", "who": "", "voice": "narrator", "diary": false}, {"start": 943.83, "end": 951.36, "text": "फिर वो घुटनों पर उठा, और फिर, ढोल अपने शिखर पर, उसने एक ऐसी चीख़ निकाली,", "who": "", "voice": "narrator", "diary": false}, {"start": 951.36, "end": 957.0, "text": "जो सीधी मेरी पसलियों के आर-पार गई, और सब कुछ रोक दिया।", "who": "", "voice": "narrator", "diary": false}, {"start": 957.7, "end": 960.74, "text": "ढोल एक साथ, एकदम चुप हो गए।", "who": "", "voice": "narrator", "diary": false}, {"start": 961.44, "end": 964.2, "text": "उस ख़ामोशी में, डंगरिया बोला।", "who": "", "voice": "narrator", "diary": false}, {"start": 964.2, "end": 966.76, "text": "उसकी आवाज़ पहले से गहरी थी।", "who": "", "voice": "narrator", "diary": false}, {"start": 966.76, "end": 967.33, "text": "स्थिर।", "who": "", "voice": "narrator", "diary": false}, {"start": 967.33, "end": 967.8, "text": "शांत।", "who": "", "voice": "narrator", "diary": false}, {"start": 967.8, "end": 969.23, "text": "उसकी अपनी नहीं।", "who": "", "voice": "narrator", "diary": false}, {"start": 969.68, "end": 971.39, "text": "परिवार ने सिर झुकाया।", "who": "", "voice": "narrator", "diary": false}, {"start": 971.39, "end": 972.53, "text": "दादी रो पड़ीं।", "who": "", "voice": "narrator", "diary": false}, {"start": 972.53, "end": 976.27, "text": "पिता ने, हाथ जोड़े हुए, धीरे से, कुमाऊँनी में,", "who": "", "voice": "narrator", "diary": false}, {"start": 976.27, "end": 979.37, "text": "अपने बेटे के बारे में बोलना शुरू किया।", "who": "", "voice": "narrator", "diary": false}, {"start": 979.37, "end": 980.51, "text": "देवता ने सुना।", "who": "", "voice": "narrator", "diary": false}, {"start": 980.51, "end": 984.5, "text": "फिर देवता ने जवाब दिया, देर तक, और मुझे नहीं पता,", "who": "", "voice": "narrator", "diary": false}, {"start": 984.5, "end": 988.4, "text": "उसने क्या कहा, और वो मेरे जानने की चीज़ नहीं है।", "who": "", "voice": "narrator", "diary": false}, {"start": 988.4, "end": 994.92, "text": "इजा ने मुझे बाद में बस इतना बताया: कि लड़के के लिए नदी पर एक मसान पूजा की जाएगी,", "who": "", "voice": "narrator", "diary": false}, {"start": 994.92, "end": 997.28, "text": "और परिवार को शांत रहना चाहिए।", "who": "", "voice": "narrator", "diary": false}, {"start": 997.73, "end": 999.46, "text": "फिर डंगरिया ने अपना सिर घुमाया।", "who": "", "voice": "narrator", "diary": false}, {"start": 999.91, "end": 1001.98, "text": "उसने आग के पार देखा।", "who": "", "voice": "narrator", "diary": false}, {"start": 1001.98, "end": 1003.43, "text": "परिवार के पार।", "who": "", "voice": "narrator", "diary": false}, {"start": 1003.43, "end": 1004.57, "text": "इजा के पार।", "who": "", "voice": "narrator", "diary": false}, {"start": 1004.57, "end": 1005.09, "text": "मुझे।", "who": "", "voice": "narrator", "diary": false}, {"start": 1005.54, "end": 1009.79, "text": "मुझे नहीं पता, उस तरह देखे जाने का एहसास कैसे बताऊँ।", "who": "", "voice": "narrator", "diary": false}, {"start": 1009.79, "end": 1015.28, "text": "जैसे मैंने आज तक जो भी बेवक़ूफ़ी की हो, और जो भी सच्ची बात सोची हो,", "who": "", "voice": "narrator", "diary": false}, {"start": 1015.28, "end": 1019.7, "text": "सब एक मेज़ पर बिछा दी गई हो, और कोई उन्हें पढ़ रहा हो,", "who": "", "voice": "narrator", "diary": false}, {"start": 1019.7, "end": 1022.08, "text": "धीरे-धीरे, बिना फ़ैसला सुनाए।", "who": "", "voice": "narrator", "diary": false}, {"start": 1022.53, "end": 1027.97, "text": "और देवता बोले, हिंदी में, इतने साफ़, कि हम सब सुन सकें।", "who": "", "voice": "narrator", "diary": false}, {"start": 1028.42, "end": 1032.16, "text": "जो पहाड़ ने लिया है, उसे वापस मत माँगो।", "who": "देवता", "voice": "god", "diary": false}, {"start": 1032.61, "end": 1036.62, "text": "फिर उसकी आँखें बंद हो गईं, और वो नीचे बैठ गया,", "who": "", "voice": "narrator", "diary": false}, {"start": 1036.62, "end": 1040.9, "text": "और ढोल फिर शुरू हुए, धीरे से, और देवता घर चले गए।", "who": "", "voice": "narrator", "diary": false}, {"start": 1041.35, "end": 1043.03, "text": "मैं देर तक हिला नहीं।", "who": "", "voice": "narrator", "diary": false}, {"start": 1043.03, "end": 1044.87, "text": "मेरे पास कोई नहीं हिला।", "who": "", "voice": "narrator", "diary": false}, {"start": 1045.32, "end": 1048.03, "text": "जब आख़िरकार मैंने अपना सिर घुमाया,", "who": "", "voice": "narrator", "diary": false}, {"start": 1048.03, "end": 1051.22, "text": "मैंने पीछे की दीवार के पास गोलू को देखा।", "who": "", "voice": "narrator", "diary": false}, {"start": 1051.92, "end": 1052.88, "text": "वो रो रहा था।", "who": "", "voice": "narrator", "diary": false}, {"start": 1053.58, "end": 1054.66, "text": "ज़ोर से नहीं।", "who": "", "voice": "narrator", "diary": false}, {"start": 1054.66, "end": 1058.45, "text": "उस आदमी की तरह नहीं, जो चाहता हो, कि कोई देखे।", "who": "", "voice": "narrator", "diary": false}, {"start": 1058.45, "end": 1062.58, "text": "ख़ामोश आँसू, उसके चेहरे से बहकर कॉलर में जाते हुए,", "who": "", "voice": "narrator", "diary": false}, {"start": 1062.58, "end": 1067.45, "text": "जबड़ा कसकर बंद, आँखें उस जगह पर टिकी, जहाँ डंगरिया बैठा था।", "who": "", "voice": "narrator", "diary": false}, {"start": 1067.45, "end": 1070.67, "text": "एक आदमी, जिसने अभी-अभी कुछ ऐसा सुना था,", "who": "", "voice": "narrator", "diary": false}, {"start": 1070.67, "end": 1074.39, "text": "जो उसे बहुत लंबे वक़्त से सुनने की ज़रूरत थी,", "who": "", "voice": "narrator", "diary": false}, {"start": 1074.39, "end": 1076.7, "text": "या जिसे सुनने से वो डरता था।", "who": "", "voice": "narrator", "diary": false}, {"start": 1077.15, "end": 1078.86, "text": "क्षितिज ने भी देखा।", "who": "", "voice": "narrator", "diary": false}, {"start": 1078.86, "end": 1080.57, "text": "उसने कुछ नहीं लिखा।", "who": "", "voice": "narrator", "diary": false}, {"start": 1080.57, "end": 1082.91, "text": "इस पूरे सफ़र में पहली बार,", "who": "", "voice": "narrator", "diary": false}, {"start": 1082.91, "end": 1086.51, "text": "उसने अपनी डायरी बंद की, और बस देखता रहा।", "who": "", "voice": "narrator", "diary": false}, {"start": 1086.96, "end": 1091.68, "text": "मैं आपको बताता हूँ, मैंने क्या सोचा, सरयू के ऊपर एक गाँव में,", "who": "", "voice": "narrator", "diary": false}, {"start": 1091.68, "end": 1094.93, "text": "सुबह चार बजे, उस बुझती आग के पास बैठे हुए।", "who": "", "voice": "narrator", "diary": false}, {"start": 1094.93, "end": 1100.36, "text": "मैंने औली में रोहन के बारे में सोचा: मैं एक पोर्टर के साथ काम करता था।", "who": "", "voice": "narrator", "diary": false}, {"start": 1100.36, "end": 1101.21, "text": "जवान लड़का।", "who": "", "voice": "narrator", "diary": false}, {"start": 1101.21, "end": 1102.52, "text": "बर्फ़ पर कमाल का।", "who": "", "voice": "narrator", "diary": false}, {"start": 1102.52, "end": 1104.38, "text": "उसे पुराने गाने पसंद थे।", "who": "", "voice": "narrator", "diary": false}, {"start": 1104.38, "end": 1108.1, "text": "मैंने द्रोणागिरी में कमला देवी के बारे में सोचा,", "who": "", "voice": "narrator", "diary": false}, {"start": 1108.1, "end": 1112.05, "text": "जो एक यूट्यूबर से, जो भाग गया था, कह रही थीं, गौरव?", "who": "", "voice": "narrator", "diary": false}, {"start": 1112.05, "end": 1117.62, "text": "और मैंने एक वाक्य के बारे में सोचा, जो एक देवता की आवाज़ में कहा गया था,", "who": "", "voice": "narrator", "diary": false}, {"start": 1117.62, "end": 1119.71, "text": "जो पहाड़ ने लिया है, और ये,", "who": "", "voice": "narrator", "diary": false}, {"start": 1119.71, "end": 1122.89, "text": "कि उस आँगन में वो किसके लिए कहा गया होगा।", "who": "", "voice": "narrator", "diary": false}, {"start": 1123.34, "end": 1126.19, "text": "मैंने ख़यालों को जोड़ा नहीं।", "who": "", "voice": "narrator", "diary": false}, {"start": 1126.19, "end": 1127.1, "text": "अभी नहीं।", "who": "", "voice": "narrator", "diary": false}, {"start": 1127.1, "end": 1132.7, "text": "मैं बहुत थका हुआ था, बहुत भावुक, और बहुत बड़ा बेवक़ूफ़।", "who": "", "voice": "narrator", "diary": false}, {"start": 1133.15, "end": 1135.26, "text": "लेकिन मैं आपको अभी बता रहा हूँ,", "who": "", "voice": "narrator", "diary": false}, {"start": 1135.26, "end": 1138.67, "text": "ताकि आप ये न कह सकें, कि मैंने चेतावनी नहीं दी थी।", "who": "", "voice": "narrator", "diary": false}, {"start": 1139.12, "end": 1140.34, "text": "मज़ाक़ वापस चालू हैं।", "who": "", "voice": "narrator", "diary": false}, {"start": 1140.34, "end": 1141.57, "text": "आप पैर फैला सकते हैं।", "who": "", "voice": "narrator", "diary": false}, {"start": 1143.07, "end": 1146.8, "text": "सुबह, जब परिवार लड़के को नीचे नदी पर ले जा रहा था,", "who": "", "voice": "narrator", "diary": false}, {"start": 1146.8, "end": 1148.45, "text": "गब्बर का फ़ोन बज़ हुआ।", "who": "", "voice": "narrator", "diary": false}, {"start": 1148.9, "end": 1151.34, "text": "उन्होंने उसे देखा, और एकदम स्थिर हो गए।", "who": "", "voice": "narrator", "diary": false}, {"start": 1151.34, "end": 1154.41, "text": "फिर उन्होंने स्क्रीन घुमाई, और मेरी तरफ़ बढ़ा दी।", "who": "", "voice": "narrator", "diary": false}, {"start": 1155.11, "end": 1155.99, "text": "अननोन नंबर।", "who": "", "voice": "narrator", "diary": false}, {"start": 1156.69, "end": 1158.05, "text": "बहुत सुंदर जागर था।", "who": "", "voice": "narrator", "diary": false}, {"start": 1158.05, "end": 1160.86, "text": "इजा जी का खाना भी बहुत तारीफ़ लायक़ है।", "who": "", "voice": "narrator", "diary": false}, {"start": 1160.86, "end": 1161.94, "text": "सुबह मिलते हैं।", "who": "", "voice": "narrator", "diary": false}, {"start": 1161.94, "end": 1162.15, "text": "आर.", "who": "", "voice": "narrator", "diary": false}, {"start": 1162.6, "end": 1165.94, "text": "किसी ने रोहन को नहीं बताया था, कि हम यहाँ हैं।", "who": "", "voice": "narrator", "diary": false}, {"start": 1165.94, "end": 1167.68, "text": "कोई बता ही नहीं सकता था।", "who": "", "voice": "narrator", "diary": false}, {"start": 1167.68, "end": 1171.75, "text": "गब्बर ने अपने परिवार के अलावा किसी को नहीं बताया था, और…", "who": "", "voice": "narrator", "diary": false}, {"start": 1172.2, "end": 1174.44, "text": "गब्बर का चेहरा राख जैसा हो गया।", "who": "", "voice": "narrator", "diary": false}, {"start": 1174.89, "end": 1179.28, "text": "शाओनी धीरे से मुड़ी, आँगन की पिछली दीवार की तरफ़ देखने।", "who": "", "voice": "narrator", "diary": false}, {"start": 1179.98, "end": 1181.18, "text": "गोलू जा चुका था।", "who": "", "voice": "narrator", "diary": false}, {"start": 1181.88, "end": 1183.56, "text": "क्षितिज की डायरी से।", "who": "", "voice": "narrator", "diary": true}, {"start": 1183.56, "end": 1186.26, "text": "डे टेन, सरयू के ऊपर इजा का गाँव।", "who": "", "voice": "narrator", "diary": true}, {"start": 1186.71, "end": 1190.73, "text": "दीदी अँधेरे से भल्ला का नाम पुकारकर उससे बच निकलीं,", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1190.73, "end": 1191.99, "text": "एक ख़बीस की तरह।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1191.99, "end": 1193.57, "text": "उसने जवाब नहीं दिया।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1193.57, "end": 1194.43, "text": "वो छुप गया।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1194.43, "end": 1196.41, "text": "भल्ला सारे नियम मानता है।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1196.41, "end": 1197.35, "text": "ये याद रखना।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1197.35, "end": 1198.93, "text": "ये हमें बचा सकता है।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1199.38, "end": 1202.75, "text": "भल्ला ने पत्थरों की स्लाइड में दीदी को बचाया।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1202.75, "end": 1204.7, "text": "अपनी पीठ पर दो पत्थर झेले।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1204.7, "end": 1208.22, "text": "आधी रात को उसने अँधेरे से कहा: माफ़ कर दे, भाई।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1208.22, "end": 1209.72, "text": "मैं कुछ नहीं कर सका।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1209.72, "end": 1210.55, "text": "भाई कौन है?", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1210.55, "end": 1211.15, "text": "बाँसुरी।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1211.15, "end": 1211.52, "text": "गाने।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1211.52, "end": 1212.27, "text": "यहाँ नहीं।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1212.27, "end": 1216.4, "text": "भल्ला इस पहाड़ पर पहले आ चुका है, और कोई नीचे नहीं आया।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1216.85, "end": 1220.43, "text": "देवता ने पार्थ भाई से कहा: जो पहाड़ ने लिया है,", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1220.43, "end": 1221.8, "text": "उसे वापस मत माँगो।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1221.8, "end": 1225.53, "text": "मैं नहीं लिख रहा, कि मुझे इसका क्या मतलब लगता है।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1225.53, "end": 1226.21, "text": "अभी नहीं।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1226.66, "end": 1229.23, "text": "गोलू जागर में बिना कैमरे के आया।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1229.23, "end": 1231.08, "text": "जब देवता बोले, वो रोया।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1231.08, "end": 1235.49, "text": "जो आदमी रोहन के लिए काम करता है, वो जागर में नहीं रोता।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1235.49, "end": 1236.61, "text": "दीदी सहमत हैं।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1237.06, "end": 1241.84, "text": "फिर आर. ने गब्बर भैया को मैसेज किया: उसे पता था, हम यहाँ हैं।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1241.84, "end": 1242.86, "text": "गोलू यहाँ था।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1242.86, "end": 1243.88, "text": "गोलू चला गया।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1243.88, "end": 1246.39, "text": "दीदी नहीं मानतीं, कि वो गोलू था।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1246.39, "end": 1249.29, "text": "वो कहती हैं: बहुत ज़्यादा ऑब्वियस है।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1249.29, "end": 1251.17, "text": "गब्बर ने और किसको बताया?", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1251.17, "end": 1253.45, "text": "गब्बर भैया ने जवाब नहीं दिया।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1253.9, "end": 1258.88, "text": "इजा का मायका, बहुत ऊपर है, बर्फ़ का गाँव, अब वहाँ कोई नहीं रहता।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1258.88, "end": 1261.6, "text": "उन्होंने ये मुझे टोपी देते हुए कहा।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1261.6, "end": 1262.77, "text": "मैंने नाम पूछा।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1262.77, "end": 1264.25, "text": "फिर ढोल शुरू हो गए।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1264.25, "end": 1265.03, "text": "फिर पूछना।", "who": "क्षितिज", "voice": "kshitij", "diary": true}], "scenes": [{"at": 20.52, "bed": "vigil"}, {"at": 57.66, "bed": "dawn"}, {"at": 80.78, "bed": "roadday"}, {"at": 155.32, "bed": "night"}, {"at": 225.72, "bed": "fog"}, {"at": 275.14, "bed": "roadday"}, {"at": 305.57, "bed": "tender"}, {"at": 358.17, "bed": "drive"}, {"at": 394.06, "bed": "village"}, {"at": 480.09, "bed": "dining"}, {"at": 538.32, "bed": "tender"}, {"at": 560.03, "bed": "stillness"}, {"at": 586.17, "bed": "lore"}, {"at": 690.49, "bed": "night"}, {"at": 734.2, "bed": "jagar"}, {"at": 830.05, "bed": "jagarrise"}, {"at": 915.32, "bed": "jagarpeak"}, {"at": 956.5, "bed": "stillness"}, {"at": 1040.15, "bed": "jagar"}, {"at": 1050.72, "bed": "tender"}, {"at": 1085.76, "bed": "bench"}, {"at": 1141.87, "bed": "morning"}, {"at": 1147.7, "bed": "threat"}, {"at": 1180.68, "bed": "diary"}, {"at": 1180.68, "bed": "diary"}], "hits": [{"at": 53.15, "fx": "thud"}, {"at": 202.81, "fx": "sting"}, {"at": 272.01, "fx": "zip"}, {"at": 459.74, "fx": "thud"}, {"at": 512.27, "fx": "phonering"}, {"at": 561.08, "fx": "drumhit"}, {"at": 895.02, "fx": "sting_light"}, {"at": 957.55, "fx": "silence"}, {"at": 1032.46, "fx": "bell"}, {"at": 1138.97, "fx": "sting_light"}, {"at": 1154.96, "fx": "ping"}, {"at": 1172.05, "fx": "sting"}, {"at": 1179.83, "fx": "sting"}, {"at": 1236.91, "fx": "sting_light"}, {"at": 1253.75, "fx": "sting"}], "next": {"label": "एपिसोड 10", "en": "Dear God, Please Find Attached", "hook": "दस हज़ार घंटियाँ। इंसाफ़ की अर्ज़ियाँ। और एक ख़बर, जो सब बदल देती है।"}};
